<?php require 'admin_guard.php'; require 'admin_db.php'; $msg=''; $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $code=trim($_POST['coursecode']);$name=trim($_POST['name']);$desc=trim($_POST['description']);$credit=(float)$_POST['credit'];$mark=(float)$_POST['total_mark'];$admin=$_SESSION['AdminID'];$pre=$_POST['prereq']??[];
 $ok=true; foreach($pre as $p){$p=trim($p); if($p==='')continue; $s=mysqli_prepare($conn,'SELECT coursecode FROM course WHERE coursecode=?');mysqli_stmt_bind_param($s,'s',$p);mysqli_stmt_execute($s);if(!mysqli_fetch_assoc(mysqli_stmt_get_result($s))){$err="Prerequisite $p is not added yet. Add it first.";$ok=false;break;}}
 if($ok){$s=mysqli_prepare($conn,'SELECT coursecode FROM course WHERE coursecode=?');mysqli_stmt_bind_param($s,'s',$code);mysqli_stmt_execute($s);if(mysqli_fetch_assoc(mysqli_stmt_get_result($s)))$err='Course code already exists.';else{$s=mysqli_prepare($conn,'INSERT INTO course(coursecode,name,description,credit,total_mark,admin) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'sssdds',$code,$name,$desc,$credit,$mark,$admin);if(mysqli_stmt_execute($s)){foreach($pre as $p){if(trim($p)!==''){ $x=mysqli_prepare($conn,'INSERT INTO course_prerequisite(coursecode,prereq_code,prereq_type) VALUES(?,?,?)');$type=$_POST['pretype'][$p]??'HARD';mysqli_stmt_bind_param($x,'sss',$code,$p,$type);mysqli_stmt_execute($x);}}$msg='Course added successfully.';}}}}
$cs=mysqli_query($conn,'SELECT coursecode,name FROM course ORDER BY coursecode'); ?>
<!doctype html><html><head><title>Add Course</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><a href="allcourse.php">← Back</a><div class="panel"><h1>Add Course</h1><?php if($err)echo'<div class="notice">'.htmlspecialchars($err).'</div>';if($msg)echo'<div class="notice">'.htmlspecialchars($msg).'</div>';?><form method="post"><label>Course Code</label><input name="coursecode" maxlength="10" required><label>Course Name</label><input name="name" required><label>Description</label><textarea name="description" required></textarea><label>Credit</label><input type="number" step="0.01" name="credit" required><label>Total Mark</label><input type="number" name="total_mark" required><h3>Prerequisites</h3><p class="muted">Only courses already present in the course table can be selected. Leave empty for no prerequisite.</p><div class="check"><?php while($c=mysqli_fetch_assoc($cs)): ?><label><input type="checkbox" name="prereq[]" value="<?=$c['coursecode']?>"> <?=htmlspecialchars($c['coursecode'].' - '.$c['name'])?> <select name="pretype[<?=htmlspecialchars($c['coursecode'])?>]"><option value="HARD">Hard</option><option value="SOFT">Soft</option></select></label><?php endwhile;?></div><button>Submit Course</button></form></div></div></body></html>
